const stdout = $input.item.json.stdout || '';
const idea = stdout.match(/Đã lưu ý tưởng: (\S+\.txt)/);
const slug = stdout.match(/Slug: (.+)/);
if (!idea || !slug) {
  throw new Error('Không parse được output bắt trend:\n' + stdout + '\n' + ($input.item.json.stderr || ''));
}
return [{
  json: {
    idea_file: idea[1],
    slug: slug[1].trim(),
  }
}];

const stdout = $input.item.json.stdout || '';
const m = stdout.match(/Đã lưu kịch bản: (\S+\.json)/);
if (!m) {
  throw new Error('Không parse được đường dẫn kịch bản từ output:\n' + stdout + '\n' + ($input.item.json.stderr || ''));
}
return [{
  json: {
    ...$('Parse Stage 0').item.json,
    script_path: m[1],
  }
}];

const stdout = $input.item.json.stdout || '';
const wav = stdout.match(/Đã lưu audio: (\S+\.wav)/);
const meta = stdout.match(/Metadata: (\S+\.json)/);
if (!wav || !meta) {
  throw new Error('Không parse được output TTS:\n' + stdout + '\n' + ($input.item.json.stderr || ''));
}
return [{
  json: {
    ...$('Parse Stage 1').item.json,
    audio_wav: wav[1],
    audio_json: meta[1],
  }
}];

const stdout = $input.item.json.stdout || '';
const meta = stdout.match(/Metadata: (\S+\.json)/);
if (!meta) {
  throw new Error('Không parse được output ảnh:\n' + stdout + '\n' + ($input.item.json.stderr || ''));
}
return [{
  json: {
    ...$('Parse Stage 2').item.json,
    images_json: meta[1],
  }
}];

const stdout = $input.item.json.stdout || '';
const m = stdout.match(/Đã render video vào (\S+\.mp4)/);
if (!m) {
  throw new Error('Không parse được output video:\n' + stdout + '\n' + ($input.item.json.stderr || ''));
}
return [{
  json: {
    ...$('Parse Stage 3').item.json,
    video_path: m[1],
  }
}];

const stdout = $input.item.json.stdout || '';
const m = stdout.match(/Đã lưu thumbnail: (\S+\.png)/);
if (!m) {
  throw new Error('Không parse được output thumbnail:\n' + stdout + '\n' + ($input.item.json.stderr || ''));
}
return [{
  json: {
    ...$('Parse Stage 4').item.json,
    thumbnail_path: m[1],
  }
}];

const stdout = $input.item.json.stdout || '';
const txt = stdout.match(/Đã lưu metadata SEO: (\S+\.txt)/);
const meta = stdout.match(/JSON: (\S+\.json)/);
const renamed = stdout.match(/Video đã đổi tên: (\S+\.mp4)/);
if (!txt || !meta) {
  throw new Error('Không parse được output metadata:\n' + stdout + '\n' + ($input.item.json.stderr || ''));
}
const prev = $('Parse Stage 5').item.json;
return [{
  json: {
    ...prev,
    metadata_txt: txt[1],
    metadata_json: meta[1],
    // Stage 6 đổi tên file .mp4 tại chỗ — tên cũ không còn tồn tại.
    final_video_path: renamed ? renamed[1] : prev.video_path,
  }
}];

const stdout = $input.item.json.stdout || '';
const m = stdout.match(/Đã render ([0-9]+) short vào (\S+)/);
if (!m) {
  throw new Error('Không parse được output short:\n' + stdout + '\n' + ($input.item.json.stderr || ''));
}
return [{
  json: {
    ...$('Parse Stage 6').item.json,
    short_count: m[1],
  }
}];

const stdout = $input.item.json.stdout || '';
const url = stdout.match(/Đã upload: (\S+)/);
const privacy = stdout.match(/Trạng thái: (.+)/);
if (!url) {
  throw new Error('Không parse được output upload:\n' + stdout + '\n' + ($input.item.json.stderr || ''));
}
return [{
  json: {
    ...$('Parse Stage 7').item.json,
    video_url: url[1],
    privacy_status: privacy ? privacy[1].trim() : 'unknown',
    thumbnail_set: /Thumbnail: đã đặt/.test(stdout),
  }
}];
